/**
 * Guardian service (V1.1 Phase 1) — owner-approved security model:
 *
 * - Pairing codes are generated by the server (`create_pairing_code` RPC);
 *   only their SHA-256 hash is stored, they expire in 15 minutes, and they
 *   are single-use.
 * - Redeeming a code creates a PENDING link only. Location access begins
 *   solely when the owner approves (`approve_link` RPC). A code alone
 *   NEVER grants access.
 * - All reads/writes are enforced by Postgres RLS (see supabase/migrations);
 *   this client never bypasses it (anon key + user JWT only).
 * - Turning sharing OFF purges the user's stored locations server-side
 *   (`set_sharing_enabled(false)`), and revoking the last active guardian
 *   purges them too.
 *
 * When Supabase is not configured, NotConfiguredGuardianService reports
 * isConfigured() = false and every operation throws GuardianNotConfiguredError
 * so screens can show the honest "not configured yet" state.
 */
import type { SupabaseClient } from '@supabase/supabase-js';
import { getSupabaseClient } from './supabaseClient';

export class GuardianNotConfiguredError extends Error {
  constructor() {
    super('Guardian service is not configured yet');
    this.name = 'GuardianNotConfiguredError';
  }
}

export class GuardianServiceError extends Error {
  constructor(message: string) {
    super(message);
    this.name = 'GuardianServiceError';
  }
}

export type GuardianLinkStatus = 'pending' | 'active' | 'revoked';

export interface GuardianUser {
  id: string;
  email: string | null;
}

export interface GuardianLink {
  id: string;
  ownerId: string;
  guardianId: string;
  status: GuardianLinkStatus;
  createdAt: string;
  /** Display name of the OTHER party (guardian for the owner view). */
  otherPartyName: string | null;
}

export interface PairingCode {
  code: string;
  /** Server-set: 15 minutes after creation. */
  expiresAt: string;
}

export interface LocationPointInput {
  lat: number;
  lng: number;
  accuracyM: number | null;
  recordedAt: string; // ISO
}

export interface LatestLocation {
  userId: string;
  lat: number;
  lng: number;
  accuracyM: number | null;
  recordedAt: string;
  updatedAt: string;
}

export interface GuardianService {
  isConfigured(): boolean;
  getCurrentUser(): Promise<GuardianUser | null>;
  signIn(email: string, password: string): Promise<GuardianUser>;
  signUp(email: string, password: string): Promise<GuardianUser | null>;
  signOut(): Promise<void>;
  /** Server generates the code; the raw value is returned exactly once. */
  createPairingCode(): Promise<PairingCode>;
  /** Redeem a code -> creates a PENDING link (never active). */
  redeemPairingCode(code: string): Promise<{ ownerId: string; status: GuardianLinkStatus }>;
  listPendingRequests(): Promise<GuardianLink[]>;
  listMyGuardians(): Promise<GuardianLink[]>;
  approveLink(linkId: string): Promise<void>;
  /** Deny a pending request (same server function as revoke). */
  denyLink(linkId: string): Promise<void>;
  revokeLink(linkId: string): Promise<void>;
  /** false => server purges the caller's stored locations immediately. */
  setSharingEnabled(enabled: boolean): Promise<void>;
  uploadLocationPoints(points: LocationPointInput[]): Promise<void>;
  getLatestLocation(userId: string): Promise<LatestLocation | null>;
}

interface LinkRow {
  id: string;
  owner_id: string;
  guardian_id: string;
  status: GuardianLinkStatus;
  created_at: string;
}

export class SupabaseGuardianService implements GuardianService {
  constructor(private client: SupabaseClient) {}

  isConfigured(): boolean {
    return true;
  }

  async getCurrentUser(): Promise<GuardianUser | null> {
    const { data } = await this.client.auth.getUser();
    if (!data.user) return null;
    return { id: data.user.id, email: data.user.email ?? null };
  }

  async signIn(email: string, password: string): Promise<GuardianUser> {
    const { data, error } = await this.client.auth.signInWithPassword({ email, password });
    if (error) throw new GuardianServiceError(error.message);
    return { id: data.user.id, email: data.user.email ?? null };
  }

  async signUp(email: string, password: string): Promise<GuardianUser | null> {
    const { data, error } = await this.client.auth.signUp({ email, password });
    if (error) throw new GuardianServiceError(error.message);
    if (!data.user) return null;
    return { id: data.user.id, email: data.user.email ?? null };
  }

  async signOut(): Promise<void> {
    const { error } = await this.client.auth.signOut();
    if (error) throw new GuardianServiceError(error.message);
  }

  private async requireUserId(): Promise<string> {
    const user = await this.getCurrentUser();
    if (!user) throw new GuardianServiceError('not signed in');
    return user.id;
  }

  async createPairingCode(): Promise<PairingCode> {
    const { data, error } = await this.client.rpc('create_pairing_code');
    if (error) throw new GuardianServiceError(error.message);
    const payload = data as { code: string; expires_at: string };
    return { code: payload.code, expiresAt: payload.expires_at };
  }

  async redeemPairingCode(code: string): Promise<{ ownerId: string; status: GuardianLinkStatus }> {
    const { data, error } = await this.client.rpc('redeem_pairing_code', { p_code: code });
    if (error) throw new GuardianServiceError(error.message);
    const payload = data as { owner_id: string; status: GuardianLinkStatus };
    return { ownerId: payload.owner_id, status: payload.status };
  }

  private async namesFor(userIds: string[]): Promise<Map<string, string | null>> {
    const map = new Map<string, string | null>();
    if (userIds.length === 0) return map;
    const { data } = await this.client.from('profiles').select('id, display_name').in('id', userIds);
    for (const row of (data ?? []) as { id: string; display_name: string | null }[]) {
      map.set(row.id, row.display_name);
    }
    return map;
  }

  private async listLinks(status: GuardianLinkStatus): Promise<GuardianLink[]> {
    const uid = await this.requireUserId();
    const { data, error } = await this.client
      .from('guardian_links')
      .select('id, owner_id, guardian_id, status, created_at')
      .eq('owner_id', uid)
      .eq('status', status)
      .order('created_at', { ascending: false });
    if (error) throw new GuardianServiceError(error.message);
    const rows = (data ?? []) as LinkRow[];
    const names = await this.namesFor(rows.map((r) => r.guardian_id));
    return rows.map((r) => ({
      id: r.id,
      ownerId: r.owner_id,
      guardianId: r.guardian_id,
      status: r.status,
      createdAt: r.created_at,
      otherPartyName: names.get(r.guardian_id) ?? null,
    }));
  }

  listPendingRequests(): Promise<GuardianLink[]> {
    return this.listLinks('pending');
  }

  listMyGuardians(): Promise<GuardianLink[]> {
    return this.listLinks('active');
  }

  async approveLink(linkId: string): Promise<void> {
    const { error } = await this.client.rpc('approve_link', { p_link_id: linkId });
    if (error) throw new GuardianServiceError(error.message);
  }

  async denyLink(linkId: string): Promise<void> {
    const { error } = await this.client.rpc('revoke_link', { p_link_id: linkId });
    if (error) throw new GuardianServiceError(error.message);
  }

  async revokeLink(linkId: string): Promise<void> {
    const { error } = await this.client.rpc('revoke_link', { p_link_id: linkId });
    if (error) throw new GuardianServiceError(error.message);
  }

  async setSharingEnabled(enabled: boolean): Promise<void> {
    const { error } = await this.client.rpc('set_sharing_enabled', { p_enabled: enabled });
    if (error) throw new GuardianServiceError(error.message);
  }

  async uploadLocationPoints(points: LocationPointInput[]): Promise<void> {
    if (points.length === 0) return;
    const uid = await this.requireUserId();
    const rows = points.map((p) => ({
      user_id: uid,
      lat: p.lat,
      lng: p.lng,
      accuracy_m: p.accuracyM,
      recorded_at: p.recordedAt,
      source: 'foreground',
    }));
    const { error } = await this.client.from('location_points').insert(rows);
    if (error) throw new GuardianServiceError(error.message);
  }

  async getLatestLocation(userId: string): Promise<LatestLocation | null> {
    const { data, error } = await this.client
      .from('latest_locations')
      .select('user_id, lat, lng, accuracy_m, recorded_at, updated_at')
      .eq('user_id', userId)
      .maybeSingle();
    if (error) throw new GuardianServiceError(error.message);
    if (!data) return null;
    const row = data as {
      user_id: string;
      lat: number;
      lng: number;
      accuracy_m: number | null;
      recorded_at: string;
      updated_at: string;
    };
    return {
      userId: row.user_id,
      lat: row.lat,
      lng: row.lng,
      accuracyM: row.accuracy_m,
      recordedAt: row.recorded_at,
      updatedAt: row.updated_at,
    };
  }
}

export class NotConfiguredGuardianService implements GuardianService {
  isConfigured(): boolean {
    return false;
  }
  async getCurrentUser(): Promise<GuardianUser | null> {
    return null;
  }
  async signIn(): Promise<GuardianUser> {
    throw new GuardianNotConfiguredError();
  }
  async signUp(): Promise<GuardianUser | null> {
    throw new GuardianNotConfiguredError();
  }
  async signOut(): Promise<void> {
    throw new GuardianNotConfiguredError();
  }
  async createPairingCode(): Promise<PairingCode> {
    throw new GuardianNotConfiguredError();
  }
  async redeemPairingCode(): Promise<{ ownerId: string; status: GuardianLinkStatus }> {
    throw new GuardianNotConfiguredError();
  }
  async listPendingRequests(): Promise<GuardianLink[]> {
    return [];
  }
  async listMyGuardians(): Promise<GuardianLink[]> {
    return [];
  }
  async approveLink(): Promise<void> {
    throw new GuardianNotConfiguredError();
  }
  async denyLink(): Promise<void> {
    throw new GuardianNotConfiguredError();
  }
  async revokeLink(): Promise<void> {
    throw new GuardianNotConfiguredError();
  }
  async setSharingEnabled(): Promise<void> {
    throw new GuardianNotConfiguredError();
  }
  async uploadLocationPoints(): Promise<void> {
    throw new GuardianNotConfiguredError();
  }
  async getLatestLocation(): Promise<LatestLocation | null> {
    return null;
  }
}

let cachedService: GuardianService | undefined;

/** App-wide singleton: Supabase-backed when configured, honest stub otherwise. */
export function getGuardianService(): GuardianService {
  if (cachedService) return cachedService;
  const client = getSupabaseClient();
  cachedService = client ? new SupabaseGuardianService(client) : new NotConfiguredGuardianService();
  return cachedService;
}

/** Test helper. */
export function resetGuardianServiceCache(): void {
  cachedService = undefined;
}
